def frames(gi,oh=None,ow=None):
    h,w=len(gi),len(gi[0])
    cnts=C2(x for row in gi for x in row); bg=cnts.most_common(1)[0][0]
    out=[]
    for rc in range(h):
        for cc in range(w):
            b_=gi[rc][cc]
            if b_==bg: continue
            for hh in range(2,h-rc+1):
                for ww in range(2,w-cc+1):
                    if rc+hh>h or cc+ww>w: continue
                    okb=True
                    for c in range(cc,cc+ww):
                        if gi[rc][c]!=b_: okb=False;break
                        if gi[rc+hh-1][c]!=b_: okb=False;break
                    if not okb: continue
                    for r in range(rc,rc+hh):
                        if gi[r][cc]!=b_ or gi[r][cc+ww-1]!=b_: continue
                        okb=False;break
                    if not okb: continue
                    inner=[gi[r][c] for r in range(rc+1,rc+hh-1) for c in range(cc+1,cc+ww-1)]
                    if not inner: continue
                    cz=C2(inner); nz={k for k,n in cz.items() if k!=b_ and k!=bg}
                    out.append(dict(rc=rc,cc=cc,hh=hh,ww=ww,b=b_,nz=nz))
    return out

